const item = $input.first().json;
const isWebhook = item.headers !== undefined && item.body !== undefined;
const testOverrides = (isWebhook && item.body && item.body.testOverrides) || {};
return [{
  json: {
    triggerSource: isWebhook ? 'webhook' : 'schedule',
    runTimestamp: new Date().toISOString(),
    testOverrides,
  }
}];

const raw = $input.first().json;
const overrides = ($('Init Context').first().json.testOverrides || {}).overrides || {};
let ok = true, value = null, error = null;
if (raw && raw.error) {
  ok = false;
  error = typeof raw.error === 'string' ? raw.error : (raw.error.message || JSON.stringify(raw.error));
} else {
  try {
    value = raw.stargazers_count;
    if (value === undefined || value === null || Number.isNaN(Number(value))) throw new Error('missing/invalid field in response');
    value = Number(value);
  } catch (e) {
    ok = false;
    error = e.message;
  }
}
if (overrides['github_stars'] !== undefined) {
  value = Number(overrides['github_stars']);
  ok = true; error = null;
}
return [{ json: {
  source: 'github',
  metric: 'github_stars',
  value, ok, error,
}}];

