const metrics = $input.all().map(i => i.json);
const ctx = $('Init Context').first().json;
return [{ json: {
  runTimestamp: ctx.runTimestamp,
  triggerSource: ctx.triggerSource,
  metrics,
  sourceDownList: metrics.filter(m => !m.ok).map(m => m.metric),
}}];

const THRESHOLD_PCT = 15; // % deviation from rolling mean that counts as an anomaly
const MIN_HISTORY = 1;    // need at least this many prior runs to judge
const current = $('Aggregate Metrics').first().json;
const historyRows = $input.all().map(i => i.json);

const out = current.metrics.map(m => {
  const prior = historyRows
    .filter(r => r.metric_name === m.metric && typeof r.value === 'number')
    .map(r => r.value);
  const priorCount = prior.length;
  const priorMean = priorCount ? prior.reduce((a, b) => a + b, 0) / priorCount : null;
  let pctChange = null;
  let anomaly = false;
  if (m.ok && priorCount >= MIN_HISTORY && priorMean) {
    pctChange = ((m.value - priorMean) / priorMean) * 100;
    anomaly = Math.abs(pctChange) >= THRESHOLD_PCT;
  }
  return {
    metric_name: m.metric,
    source: m.source,
    value: m.ok ? m.value : null,
    ok: m.ok,
    error_note: m.error || '',
    run_timestamp: current.runTimestamp,
    prior_mean: priorMean,
    prior_count: priorCount,
    pct_change: pctChange,
    anomaly,
    threshold_pct: THRESHOLD_PCT,
  };
});
return out.map(json => ({ json }));

const metrics = $('Detect Anomalies').all().map(i => i.json);
const ctx = $('Aggregate Metrics').first().json;
const anomalyCount = metrics.filter(m => m.anomaly).length;
const sourceDownCount = metrics.filter(m => !m.ok).length;

const lines = metrics.map(m => {
  if (!m.ok) return `- ${m.metric_name}: SOURCE UNAVAILABLE (${m.error_note})`;
  const trend = m.pct_change === null ? 'no prior history yet' : `${m.pct_change >= 0 ? '+' : ''}${m.pct_change.toFixed(1)}% vs rolling mean of ${m.prior_count} prior run(s)`;
  return `- ${m.metric_name}: ${m.value} (${trend})${m.anomaly ? '  <-- ANOMALY (threshold ' + m.threshold_pct + '%)' : ''}`;
}).join('\n');

const prompt = `You are writing a crisp executive KPI digest for a portfolio automation demo.\n\nRun timestamp: ${ctx.runTimestamp}\nTrigger: ${ctx.triggerSource}\n\nMetrics this run:\n${lines}\n\nWrite a short executive digest (120-180 words, plain text, no markdown headers) that:\n1. States what moved and by how much, in plain business language.\n2. Explicitly calls out any ANOMALY metrics by name and explains why it matters.\n3. If any source is unavailable, say so plainly as a data-gap note - never silently omit it.\n4. Ends with one sentence on overall system health (normal / needs attention).\nDo not invent numbers that were not given above.`;

return [{ json: {
  prompt,
  runTimestamp: ctx.runTimestamp,
  anomalyCount,
  sourceDownCount,
  metricsJson: JSON.stringify(metrics),
}}];

const ctx = $('Build Digest Prompt').first().json;
const digestText = $json.text || '(no digest text returned)';
return [{ json: {
  run_timestamp: ctx.runTimestamp,
  digest_text: digestText,
  anomaly_count: ctx.anomalyCount,
  source_down_count: ctx.sourceDownCount,
  metrics_json: ctx.metricsJson,
}}];

